"""Small, self-contained presentation layer for the fictional AsterView camera."""

# ruff: noqa: E501 -- keeping embedded CSS and HTML contiguous makes it auditable.

from html import escape

CSS = """
:root{color-scheme:dark;--bg:#07111f;--panel:#101d2c;--line:#243b52;--blue:#2388d8;--cyan:#35d3e7;--text:#dbe8f4;--muted:#8297aa;--green:#47d18c;--amber:#e8b04a;--red:#ef5d68}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 70% 0,#102b47,var(--bg) 48%);color:var(--text);font:13px/1.5 "Segoe UI",Arial,sans-serif;min-height:100vh}a{color:inherit;text-decoration:none}.top{height:62px;padding:0 28px;background:#091522;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between}.brand{font-size:19px;font-weight:700;letter-spacing:.6px}.brand b{color:var(--cyan)}.model,.muted{color:var(--muted);font-size:12px}.layout{display:grid;grid-template-columns:210px 1fr;min-height:calc(100vh - 62px)}nav{background:#0a1624;border-right:1px solid var(--line);padding:22px 12px}nav a{display:block;padding:11px 15px;margin:3px 0;border-radius:3px;color:#a9bdcf}nav a:hover,nav a.active{background:#152c43;color:#fff;border-left:3px solid var(--blue)}main{padding:28px;max-width:1200px;width:100%}.heading{display:flex;align-items:center;justify-content:space-between;margin-bottom:18px}h1{font-size:20px;margin:0;font-weight:600}.panel{background:linear-gradient(145deg,#122234,#0e1b29);border:1px solid var(--line);border-radius:5px;padding:20px;box-shadow:0 12px 30px #0003}.grid{display:grid;grid-template-columns:minmax(0,2fr) minmax(230px,1fr);gap:18px}.viewer{position:relative;aspect-ratio:16/9;background:#02070c;border:1px solid #29445d;overflow:hidden}.viewer img{display:block;width:100%;height:100%;object-fit:cover}.overlay{position:absolute;inset:12px;pointer-events:none}.rec{float:right;color:#fff;background:#b12632cc;padding:3px 8px;border-radius:2px}.dot{display:inline-block;width:8px;height:8px;border-radius:50%;background:var(--green);margin-right:7px;box-shadow:0 0 7px var(--green)}dl{margin:0}dt,dd{padding:9px 0;border-bottom:1px solid #203548}dt{float:left;clear:left;color:var(--muted);width:46%}dd{margin-left:46%;text-align:right}.button,button{display:inline-block;border:0;border-radius:3px;background:var(--blue);color:white;padding:9px 17px;font:inherit;cursor:pointer}.button.secondary,button.secondary{background:#20384e}.cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(250px,1fr));gap:16px}.status{color:var(--green)}.warning{color:var(--amber)}.notice{padding:10px 12px;margin:0 0 16px;border-left:3px solid var(--red);background:#3a1820}.login-wrap{min-height:100vh;display:grid;place-items:center;padding:24px}.login{width:min(390px,100%);padding:34px}.camera-mark{width:54px;height:38px;border:2px solid var(--cyan);border-radius:5px;margin:0 auto 20px;position:relative}.camera-mark:after{content:"";position:absolute;width:13px;height:13px;border:2px solid var(--cyan);border-radius:50%;left:18px;top:10px}.login h1{text-align:center;font-size:24px}.login .model{text-align:center;margin-bottom:28px}.login label{display:block;color:#a8bbca;margin-top:14px}.login input{width:100%;margin-top:6px;padding:11px;background:#091522;border:1px solid #31485c;color:#fff;border-radius:3px}.login button{width:100%;margin-top:22px}.footer{text-align:center;color:#60778b;font-size:11px;margin-top:23px}.actions form{display:inline}.actions button{margin:5px 4px 0 0}@media(max-width:700px){.layout{display:block}nav{display:flex;overflow:auto;border-right:0;border-bottom:1px solid var(--line);padding:7px}nav a{white-space:nowrap}.grid{grid-template-columns:1fr}main{padding:18px}.top{padding:0 16px}}
"""


def login_page(error: bool = False) -> str:
    notice = '<div class="notice">The user name or password is incorrect.</div>' if error else ""
    return f"""<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>AsterView CV-210 | Sign In</title><style>{CSS}</style></head><body><div class="login-wrap"><section class="panel login"><div class="camera-mark"></div><h1>AsterView</h1><div class="model">CV-210 NETWORK CAMERA</div>{notice}<form method="post" action="/login"><label for="username">User Name</label><input id="username" name="username" autocomplete="username" required><label for="password">Password</label><input id="password" name="password" type="password" autocomplete="current-password" required><button type="submit">Sign In</button></form><noscript><p class="warning">JavaScript is disabled. Sign in and device pages remain available.</p></noscript><div class="footer">Firmware 2.4.7 · © 2026 AsterView Systems</div></section></div></body></html>"""


def shell(title: str, active: str, body: str, device_time: str) -> str:
    links = (("live", "Live View"), ("device", "Device"), ("network", "Network"), ("maintenance", "Maintenance"), ("firmware", "Firmware"))
    nav = "".join(f'<a class="{"active" if key == active else ""}" href="/{key}">{label}</a>' for key, label in links)
    return f"""<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>{escape(title)} | AsterView CV-210</title><style>{CSS}</style></head><body><header class="top"><div><span class="brand">Aster<b>View</b></span> <span class="model">CV-210</span></div><div><span class="dot"></span>Online &nbsp; <span class="muted">{device_time}</span></div></header><div class="layout"><nav>{nav}<a href="/logout">Logout</a></nav><main>{body}</main></div></body></html>"""


def info_table(rows: tuple[tuple[str, str], ...]) -> str:
    return "<dl>" + "".join(f"<dt>{escape(k)}</dt><dd>{escape(v)}</dd>" for k, v in rows) + "</dl>"
